WITH flattened AS (SELECT id, plan, effective_from, currency, element FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) t AS element) SELECT plan, CASE WHEN element >= 82 THEN 'PREMIUM' ELSE 'STANDARD' END AS element_tier, COUNT(*) FILTER (WHERE plan = 'enterprise') AS enterprise_rows, PERCENTILE_APPROX(element, ARRAY(0.25, 0.5, 0.75)) AS element_quartiles, COUNT(*) FILTER (WHERE currency = 'USD') AS usd_rows FROM flattened GROUP BY plan, element_tier ORDER BY usd_rows DESC NULLS LAST;
